update public.garments set subcategory = $t$pajama shirt$t$, colors = array[$t$pink$t$, $t$white$t$]::text[], material = $t$satin$t$, styling_note = $t$Perfect for a loungewear look, or worn as an outer layer in a pajama-chic style with minimalist sandals.$t$ where id = 'a4b07f86-619c-4dc8-8049-08516d2abef9';
update public.outfits set title = $t$City basics$t$, explanation = $t$This look balances the freshness of the striped t-shirt with the structure of the blue pants. The beige graphic piece on top works as a big neutral accent that protects you a little from Mexico City's mild wind.

